INSERT INTO `reviews` VALUES (1,2,2,10,'Эталонное фэнтези: масштаб, интриги и персонажи, за которых переживаешь по-настоящему.','2026-11-18 12:39:06'),(2,2,20,9,'Космос как метафора любви. Музыка Циммера и финал, который разбираешь неделями.','2026-11-17 12:39:06'),(3,3,12,9,'Редкий случай, когда научная фантастика ещё и очень смешная.','2026-11-16 12:39:06'),(4,4,1,8,'Классическая история любви, которая всё ещё работает.','2026-11-15 12:39:06'),(5,6,5,9,'Первый сезон держит в напряжении с первой до последней минуты.','2026-11-14 12:39:06'),(6,5,21,10,'Лучший фильм о надежде. Пересматриваю каждый год.','2026-11-13 12:39:06');
