  `name` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `price` decimal(8,2) NOT NULL COMMENT 'Цена со скидкой, ₽',
  `old_price` decimal(8,2) DEFAULT NULL COMMENT 'Цена без скидки, ₽',
  `period_days` smallint(5) unsigned NOT NULL COMMENT 'Срок действия, дней',
  `quality` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Full HD',
  `devices` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `features` text COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Возможности тарифа, по одному пункту в строке',
  `is_popular` tinyint(1) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` tinyint(3) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_tariff_code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
