INSERT INTO `tariffs` VALUES (1,'month','Месяц',599.00,799.00,30,'Full HD',1,'Доступ ко всем фильмам и сериалам\nПросмотр на 1 устройстве\nКачество Full HD\nОтмена в любой момент',0,1,1),(2,'quarter','3 месяца',1490.00,1990.00,92,'Full HD',2,'Всё из тарифа «Месяц»\nЭкономия 25% к месячной цене\n2 устройства одновременно\nЛичные рекомендации',0,1,2),(3,'year','Год',3990.00,5990.00,365,'4K Ultra HD',3,'Всё из тарифа «3 месяца»\nКачество 4K Ultra HD\n3 устройства одновременно\nРанний доступ к новинкам\nСкачивание для офлайн-просмотра',1,1,3),(4,'family','Семейный',6990.00,8990.00,365,'4K Ultra HD',5,'Всё из тарифа «Год»\n5 устройств и 4 профиля\nДетский режим с ограничением 6+\nПриоритетная поддержка 24/7',0,1,4);
