DROP TABLE IF EXISTS `titles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `titles` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `type` enum('movie','series') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'movie',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Название на русском',
  `original_title` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `slug` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Адрес страницы /title.php?slug=',
  `description` text COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Описание (синопсис)',
  `year` smallint(5) unsigned DEFAULT NULL COMMENT 'Год начала',
  `year_end` smallint(5) unsigned DEFAULT NULL COMMENT 'Год окончания (для сериалов)',
  `country` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `duration` smallint(5) unsigned DEFAULT NULL COMMENT 'Минуты: фильм целиком / эпизод',
  `age_limit` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Возрастной рейтинг: 0+, 6+ … 18+',
  `rating` decimal(3,1) NOT NULL DEFAULT 0.0 COMMENT 'Рейтинг Кинопоиска',
  `price` decimal(8,2) NOT NULL DEFAULT 0.00 COMMENT 'Цена покупки, ₽ (0 — только подписка)',
  `poster` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Постер в assets/img/posters',
  `backdrop` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Кадр для hero-баннера',
  `logo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'PNG-логотип названия',
  `trailer` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Видеофайл трейлера',
  `accent_color` varchar(7) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#FF6B35' COMMENT 'Акцент цвета тайтла',
  `badge` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Плашка: Новое, Топ-10 …',
  `director` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cast_list` text COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Актёры через запятую',
  `is_new` tinyint(1) NOT NULL DEFAULT 0,
  `is_popular` tinyint(1) NOT NULL DEFAULT 0,
  `views` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_titles_slug` (`slug`),
  KEY `idx_titles_type` (`type`),
  KEY `idx_titles_new` (`is_new`),
  KEY `idx_titles_popular` (`is_popular`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Каталог фильмов и сериалов';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `titles` WRITE;
/*!40000 ALTER TABLE `titles` DISABLE KEYS */;
INSERT INTO `titles` VALUES (1,'movie','Дневник памяти',NULL,'dnevnik-pamyati','История отношений юноши и девушки из разных социальных слоёв, живших в Южной Каролине. Ной и Элли провели вместе незабываемое лето, пока их не разделили сначала родители, а затем Вторая мировая война. После войны всё изменилось: Элли обручилась с удачливым бизнесменом, а Ной жил наедине со своими воспоминаниями в старинном доме, который ему удалось отреставрировать. Когда Элли прочла об этом в местной газете, она поняла: ей нужно найти его и решить наконец судьбу их любви.',2004,NULL,'США',123,'16+',8.2,0.00,'dnevnik.jpg','1.jpg','dnevnik.png','dnevnik.mp4','#81abeb','Популярное','Ник Кассаветис','Райан Гослинг, Рэйчел Макадамс, Джеймс Гарнер, Джина Роулендс',0,1,79330,'2026-11-19 12:39:05'),(2,'series','Игра престолов',NULL,'igra-prestolov','К концу подходит время благоденствия, и лето, длившееся почти десятилетие, угасает. Вокруг средоточия власти Семи королевств, Железного трона, зреет заговор, и в это непростое время король решает искать поддержки у друга юности Эддарда Старка. В мире, где все — от короля до наёмника — рвутся к власти, плетут интриги и готовы вонзить нож в спину, есть место и благородству, состраданию и любви. Между тем никто не замечает пробуждение тьмы из легенд далеко на Севере — и лишь Стена защищает живых к югу от неё.',2011,2019,'США, Великобритания',50,'18+',9.5,0.00,'igra.jpg','2.jpg','igra2.png','igra2.mp4','#545151','Новый сезон','Дэвид Бениофф, Д. Б. Уайсс','Эмилия Кларк, Кит Харингтон, Питер Динклэйдж, Лена Хиди, Шон Бин',1,1,31907,'2026-11-19 12:39:05'),(3,'movie','До встречи с тобой',NULL,'do-vstrechi-s-toboy','Лу Кларк знает, сколько шагов от автобусной остановки до её дома. Она знает, что ей очень нравится работа в кафе и что, скорее всего, она не любит своего бойфренда Патрика. Но Лу не знает, что вот-вот потеряет свою работу и что в ближайшем будущем ей понадобятся все силы, чтобы преодолеть свалившиеся на неё проблемы. Уилл Трейнор знает, что сбивший его мотоциклист отнял у него желание жить. И он точно знает, что надо сделать, чтобы положить конец всему этому. Но он не знает, что Лу скоро ворвётся в его мир буйством красок. И они оба не знают, что навсегда изменят жизнь друг друга.',2016,NULL,'США, Великобритания',110,'18+',8.7,0.00,'do.jpg','3.jpg','do.png','do.mp4','#C0392B','Топ-10','Теа Шэррок','Сэм Клафлин, Эмилия Кларк, Дженна Коулман, Мэттью Льюис',0,1,23548,'2026-11-19 12:39:05'),(4,'movie','Левша',NULL,'levsha','У боксёра Билли Хоупа всё было прекрасно: звание чемпиона, красавица-жена и любимая дочка. Но фортуна отворачивается от него: при трагических обстоятельствах погибает любимая жена, дисквалификация на ринге, нулевые доходы, суд лишает его родительских прав. Хоуп должен отстоять звание чемпиона и вернуть дочь. Есть ли у Хоупа шансы на победу? Всё решит его знаменитый хук левой.',2015,NULL,'США, Гонконг',124,'18+',8.2,249.00,'levha.jpg','4.jpg','levha.png','levha.mp4','#D4A017','Популярное','Антуан Фукуа','Джейк Джилленхол, Форест Уитакер, Рэйчел МакАдамс, Наоми Харрис',0,1,78136,'2026-11-19 12:39:05'),(5,'series','Бумажный дом',NULL,'bumazhnyy-dom','История о преступниках, решивших ограбить Королевский монетный двор Испании и украсть 2,4 млрд евро. Гениальный стратег, назвавший себя Профессором, собирает команду из восьми человек с уникальными навыками. Пока полиция пытается понять, кто стоит за дерзким преступлением, заложники внутри монетного двора становятся частью плана, а каждый участник банды рискует не только свободой, но и жизнью.',2017,2021,'Испания',50,'18+',8.2,0.00,'dom.jpg','5.jpg','dom.png','dom.mp4','#e72121','Новый сезон','Алекс Пиня','Урсула Корберо, Альваро Морте, Ициар Итуньо, Педро Алонсо',1,1,96133,'2026-11-19 12:39:05'),(6,'movie','Загадочная история Бенджамина Баттона',NULL,'zagadochnaya-istoriya','Фильм о мужчине, который родился в возрасте 80 лет, а затем начал молодеть. Этот человек, как и каждый из нас, не мог остановить время. Его путь в XXI век, берущий своё начало в Новом Орлеане в 1918 году в самом конце Первой мировой войны, будет столь необычен, что вряд ли мог иметь место в жизни кого-либо другого. Фильм повествует о судьбе уникального человека, о людях и событиях, что ждут его впереди, о любви, которую он обретёт и потеряет, о радостях жизни и грусти потерь и о том, что остаётся с нами вне времени.',2008,NULL,'США',166,'18+',8.1,0.00,'istoria.jpg','6.jpg','istoria.png','istoria.mp4','#f8ad53','Топ-10','Дэвид Финчер','Брэд Питт, Кейт Бланшетт, Тараджи П. Хенсон, Джулия Ормонд',0,1,68223,'2026-11-19 12:39:05'),(7,'movie','В метре друг от друга',NULL,'v-metre-drug-ot-druga','Пространство, в котором они существуют, диктует жестокое условие — влюблённые должны находиться не ближе метра друг от друга, им недоступно даже прикосновение. Но истинная любовь не знает границ, и чем сильнее чувства, тем больше соблазн нарушить правила.',2019,NULL,'США',116,'16+',7.4,0.00,'dryg.jpg','7.jpg','dryg.png','dryg.mp4','#d8656d','Любовь','Джастин Бальдони','Хейли Лу Ричардсон, Коул Спроус, Мойзес Ариас, Кимберли Хеберт Грегори',0,0,48389,'2026-11-19 12:39:05'),(8,'series','Энн',NULL,'enn','Энн — тринадцатилетняя сирота. Девочка рано лишилась родителей и с тех пор живёт в детском приюте. Жизнь героини резко меняется, когда в результате ошибки она попадает к новым приёмным родителям — старой деве и её младшему брату. Мечтательная и неутомимо любопытная Энн учится дружить, отстаивать себя и находить красоту в обычной жизни на ферме «Зелёные крыши».',2017,2019,'Канада',45,'12+',8.2,0.00,'nn.jpg','1.jpg','nn.png','nn.mp4','#1160a0','Популярное','Ники Каро','Эмибет Макналти, Джеральдин Джеймс, Р. Х. Томсон, Лукас Джейд Зуманн',0,1,51066,'2026-11-19 12:39:05'),(9,'movie','На Западном фронте без перемен',NULL,'na-zapadnom-fronte','Германская империя, 1917 год. Преисполненные патриотизмом 19-летний Пауль Боймер и его друзья-одноклассники отправляются добровольцами на фронт, где им предстоит испытать на себе ужасы Первой мировой войны. Окопная жизнь оказывается совсем не такой, как на пропагандистских плакатах, и каждый прожитый день становится проверкой на прочность.',2022,NULL,'Германия, США, Великобритания',148,'18+',8.0,299.00,'fronte.jpg','2.jpg','fronte.png','fronte.mp4','#a8a29a','Военный','Эдвард Бергер','Феликс Каммерер, Альбрехт Шух, Даниэль Брюль, Себастиан Хюльк',0,0,12596,'2026-11-19 12:39:05'),(10,'movie','Пираты Карибского моря: Проклятие Чёрной жемчужины',NULL,'piraty-karibskogo-morya','Жизнь харизматичного авантюриста, капитана Джека Воробья, полная увлекательных приключений, резко меняется, когда его заклятый враг капитан Барбосса похищает корабль Джека — Чёрную Жемчужину, а затем нападает на Порт-Ройал и крадёт прекрасную дочь губернатора Элизабет Суонн. Друг детства Элизабет Уилл Тёрнер вместе с Джеком возглавляет спасательную экспедицию на самом быстром корабле Британии. Однако Уилл не знает, что над Барбоссой висит вечное проклятие, при лунном свете превращающее его с командой в живых скелетов.',2003,NULL,'США',143,'12+',8.4,349.00,'pirat.jpg','3.jpg','pirat.png','pirat.mp4','#ffc265','Популярное','Гор Вербински','Джонни Депп, Орландо Блум, Кира Найтли, Джеффри Раш',0,1,92488,'2026-11-19 12:39:05'),(11,'movie','Аватар: Путь воды',NULL,'avatar','Джейк Салли, Нейтири и их дети переживают смерть Нетейама. Противостояние с корпорацией RDA обостряется, и теперь семье предстоит столкнуться с враждебным племенем На’ви во главе с Варанг. Чтобы защитить близких, героям придётся покинуть родной лес и отправиться к океану, где жизнь подчиняется другим законам.',2022,NULL,'США, Канада',192,'12+',8.6,399.00,'avatar.jpg','4.jpg','avatar.png','avatar.mp4','#4675f6','Новое','Джеймс Кэмерон','Сэм Уортингтон, Зои Салдана, Сигурни Уивер, Стивен Лэнг',1,1,75624,'2026-11-19 12:39:05'),(12,'movie','Проект «Конец света»',NULL,'proekt-konec-sveta','Микробиолог Райленд Грейс просыпается на космическом корабле, не помня ни себя, ни свою миссию. Мужчина выясняет, что он — единственный выживший из экипажа, отправленного к звезде Тау Кита в поисках спасения от катастрофы на Земле. Чтобы найти решение, Райленду предстоит положиться на свои обширные научные знания и изобретательность, но, возможно, ему не придётся искать в одиночку.',2026,NULL,'США',156,'16+',8.6,449.00,'kones.jpg','5.jpg','kones.png','kones.mp4','#feae75','Новое','Крис Миллер, Фил Лорд','Райан Гослинг, Сандра Хюллер, Джеймс Ортис',1,1,44654,'2026-11-19 12:39:05'),(13,'movie','ВАЛЛ·И',NULL,'wall-e','Робот ВАЛЛ·И из года в год прилежно трудится на опустевшей Земле, очищая нашу планету от гор мусора, которые оставили после себя улетевшие в космос люди. Он и не представляет, что совсем скоро произойдут невероятные события, благодаря которым он встретит друзей, поднимется к звёздам и даже сумеет изменить к лучшему своих бывших хозяев, совсем позабывших родную Землю.',2008,NULL,'США',98,'0+',8.4,249.00,'valli.jpg','6.jpg','valli.png','valli.mp4','#f11b1b','Семейное','Эндрю Стэнтон','Бен Бёртт, Элисса Найт, Джефф Гарлин, Фред Уиллард',0,1,50694,'2026-11-19 12:39:05'),(14,'movie','Человек, который изменил всё',NULL,'chelovek-kotoryy-izmenil-vse','2001 год. Менеджер бейсбольной команды Oakland Athletics Билли Бин после проигрыша в ключевом матче команде New York Yankees, которая обладает значительно большим бюджетом, решает в корне изменить систему подбора игроков. Во время деловой поездки в Кливленд он знакомится с молодым выпускником Йеля, экономистом Питером Брэндом, который при помощи математических расчётов предлагает внедрить новаторскую схему оценки полезности игроков, основываясь на показателях их личной статистики.',2011,NULL,'США',133,'16+',7.8,0.00,'vse.jpg','7.jpg','vse.png','vse.mp4','#72bd55','Мотивационное','Беннетт Миллер','Брэд Питт, Джона Хилл, Филип Сеймур Хоффман, Робин Райт',0,0,19583,'2026-11-19 12:39:05'),(15,'movie','500 дней лета',NULL,'500-dney-leta','Главный герой работает в агентстве, выпускающем поздравительные открытки. Он придумывает все те забавные подписи, которые мы читаем на них. Молодой человек влюбляется в свою коллегу и решает, что она — «та, единственная». Но 500 дней их отношений показывают герою, что путь к счастью непредсказуем, неконтролируем и невероятно забавен.',2009,NULL,'США',95,'16+',7.7,199.00,'500.jpg','1.jpg','500.png','500.mp4','#81abeb','Любовь','Марк Уэбб','Джозеф Гордон-Левитт, Зои Дешанель, Джеффри Аренд, Клои Грейс Морц',0,0,11001,'2026-11-19 12:39:05'),(16,'movie','Мистер и миссис Смит',NULL,'mister-i-missis-smit','Джон и Джейн женаты не так давно, но уже устали от брака. Им кажется, что они знают друг о друге всё. Но есть кое-что, что каждый предпочитает держать при себе: оба они — наёмные убийцы, которые тайно путешествуют по миру, выполняя опасные миссии. Эти отдельные тайные приключения становятся их общей судьбой в тот момент, когда Джейн получает заказ на Джона, а Джон — на Джейн.',2005,NULL,'США',120,'18+',7.6,0.00,'smit.jpg','2.jpg','smit.png','smit.mp4','#f11b1b','Топ-10','Даг Лайман','Брэд Питт, Анджелина Джоли, Винс Вон, Адам Броди',0,1,59262,'2026-11-19 12:39:05'),(17,'movie','Любовь и другие лекарства',NULL,'lyubov-i-drugie-lekarstva','Девушка широких взглядов Мэгги встречает мужчину своей мечты в лице обаятельного продавца виагры Джейми. Они начинают лёгкую интрижку, но оказывается, что надвигающаяся трагедия переворачивает их жизни. Но между Мэгги и Джейми существует особая «химия», они находятся под влиянием абсолютного наркотика по имени любовь.',2010,NULL,'США',113,'18+',6.9,0.00,'lekarstvo.jpg','3.jpg','lekarstvo.png','lekarstvo.mp4','#ffc265','Любовь','Эдвард Цвик','Джейк Джилленхол, Энн Хэтэуэй, Оливер Платт, Хэнк Азария',0,0,67086,'2026-11-19 12:39:05'),(18,'movie','Один день',NULL,'odin-den','Эмма романтична, остра на язык и хочет изменить мир к лучшему. Декстер — плейбой, баловень судьбы и хочет, чтобы мир принадлежал ему. Впервые они встретились на выпускном в колледже и провели вместе только один день. А потом пришла ночь, и они решили остаться друзьями. Каждый год 15 июля они встречаются снова — и каждое свидание меняет их жизни.',2011,NULL,'США, Великобритания',103,'16+',7.9,0.00,'odin.jpg','4.jpg','odin.png','odin.mp4','#ffc72e','Любовь','Лоне Шерфиг','Энн Хэтэуэй, Джим Стёрджесс, Том Миссон, Джоди Мэй',0,0,29850,'2026-11-19 12:39:05'),(19,'movie','Вечное сияние чистого разума',NULL,'vechnoe-siyanie','Застенчивый и меланхоличный Джоэл живёт ничем не примечательной серой и унылой жизнью. Но однажды он узнаёт, что его девушка Клементина обратилась в клинику, чтобы стереть воспоминания о нём. В отчаянии Джоэл решается на ответный шаг — стирание памяти о Клементине. Но во время процедуры он понимает, что не готов расстаться даже с болью: вместе с воспоминаниями исчезает всё, что было настоящим.',2004,NULL,'США',108,'16+',8.1,249.00,'razym.jpg','5.jpg','razym.png','razym.mp4','#f17f28','Популярное','Мишель Гондри','Джим Керри, Кейт Уинслет, Кирстен Данст, Марк Руффало',0,1,20911,'2026-11-19 12:39:05'),(20,'movie','Интерстеллар',NULL,'interstellar','Когда засуха, пыльные бури и вымирание растений приводят человечество к продовольственному кризису, коллектив исследователей и учёных отправляется сквозь червоточину в путешествие, чтобы превзойти прежние ограничения для космических путешествий человека и найти планету с подходящими для человечества условиями.',2014,NULL,'США, Великобритания, Канада',169,'16+',8.7,349.00,'intestelar.jpg','6.jpg','intestelar.png','intestelar.mp4','#e8e2d4','Популярное','Кристофер Нолан','Мэттью Макконахи, Энн Хэтэуэй, Джессика Честейн, Майкл Кейн',0,1,30090,'2026-11-19 12:39:05'),(21,'movie','Побег из Шоушенка',NULL,'pobeg-iz-shoushenka','Бухгалтер Энди Дюфрейн обвинён в убийстве собственной жены и её любовника. Оказавшись в тюрьме под названием Шоушенк, он сталкивается с жестокостью и беззаконием, царящими по обе стороны решётки. Каждый, кто попадает в эти стены, становится их рабом до конца жизни. Но Энди, обладающий живым умом и доброй душой, находит подход как к заключённым, так и к охранникам, добиваясь их особого к себе расположения.',1994,NULL,'США',142,'16+',9.1,299.00,'pobeg.jpg','7.jpg','pobeg.png','pobeg.mp4','#c9d4e0','Топ-10','Фрэнк Дарабонт','Тим Роббинс, Морган Фримен, Боб Гантон, Уильям Сэдлер',0,1,92139,'2026-11-19 12:39:05'),(22,'movie','Мост в Терабитию',NULL,'most-v-terabitiyu','Надежды ученика пятого класса Джесса Аарона стать самым быстрым бегуном в классе разбились после того, как новичок Лесли Берк одержала победу в соревнованиях. Оснований для враждебности по отношению друг к другу у Джесса и Лесли более чем достаточно, и тем не менее между ними завязывается дружба. Как тут не подружиться, если приходится быть королём и королевой в обнаруженном в лесу волшебном царстве?',2007,NULL,'США',93,'6+',7.8,199.00,'most.jpg','1.jpg','most.png','most.mp4','#F5B301','Семейное','Габор Чупо','Джош Хатчерсон, Аннасофия Робб, Зои Дешанель, Бэйли Мэдисон',0,0,85911,'2026-11-19 12:39:05'),(23,'movie','Бойфренд из будущего',NULL,'boyfrend-iz-budushchego','Тиму повезло — он молодой, симпатичный, многообещающий адвокат, а ещё он умеет перемещаться во времени. И чтобы очаровать девушку своей мечты, он готов повторять первое свидание вновь и вновь. Воистину, любовь с первого взгляда не всегда выходит с первого раза.',2013,NULL,'США, Великобритания',123,'16+',7.9,0.00,'byd.jpg','2.jpg','byd.png','byd.mp4','#8fb4c9','Популярное','Ричард Кёртис','Донал Глисон, Рэйчел Макадамс, Билл Найи, Марго Робби',0,1,9454,'2026-11-19 12:39:05'),(24,'movie','Знакомьтесь, Джо Блэк',NULL,'znakomtes-dzho-blek','В жизни газетного магната Уильяма Пэрриша появляется сама Смерть, принявшая обличье молодого человека по имени Джо Блэк. Смерть, уставшая от своих привычных обязанностей, предлагает Пэрришу необычное соглашение: магнат станет проводником Джо в мире живых, а по окончании каникул Смерть заберёт Пэрриша с собой.',1998,NULL,'США',178,'16+',8.1,199.00,'djo.jpg','3.jpg','djo.png','djo.mp4','#b8b2a7','Любовь','Мартин Брест','Брэд Питт, Энтони Хопкинс, Клэр Форлани, Джейк Уэбер',0,0,13113,'2026-11-19 12:39:05'),(25,'series','Побег',NULL,'pobeg','Майкл убеждён в невиновности брата, осуждённого на казнь, и решает сам восстановить справедливость. Он намеренно совершает преступление, за которое попадает в ту самую тюрьму, где сидит брат. Ту самую, которую Майкл хорошо знает, потому что сам же её и создавал как инженер-строитель. План спасения гениально прост, но каждая деталь может стоить жизни.',2005,2017,'США, Великобритания',43,'18+',8.4,0.00,'pobegg.jpg','4.jpg','pobegg.png','pobegg.mp4','#f5351b','Популярное','Дуайт Х. Литтл','Вентворт Миллер, Доминик Пёрселл, Робин Танни, Питер Стормаре',0,1,72367,'2026-11-19 12:39:05'),(26,'series','Очень странные дела',NULL,'ochen-strannye-dela','1980-е годы, тихий провинциальный американский городок Хокинс. Благоприятное течение местной жизни нарушает загадочное исчезновение подростка по имени Уилл. Выяснить обстоятельства дела полны решимости родные мальчика и местный шериф, а также лучший друг Уилла — Майк. Он начинает собственное расследование и оказывается в эпицентре ожесточённой битвы потусторонних сил.',2016,2025,'США',55,'16+',8.3,0.00,'osd.jpg','5.jpg','osd.png','osd.mp4','#f5351b','Популярное','Шон Леви, Мэтт Даффер, Росс Даффер','Финн Вулфхард, Милли Бобби Браун, Дэвид Харбор, Вайнона Райдер',1,1,22950,'2026-11-19 12:39:05'),(27,'series','В поисках Аляски',NULL,'v-poiskah-alyaski','Шестнадцатилетний Майлз Холтер интересуется предсмертными высказываниями известных людей. Следуя последним словам Франсуа Рабле, он оставляет скучную жизнь с родителями и отправляется учиться в новую школу Калвер-Крик в поисках «Великого Возможно». Здесь он находит первых друзей и влюбляется в девочку по имени Аляска Янг, которая переворачивает его жизнь, а потом исчезает из неё. Ужасная трагедия заставляет Майлза серьёзно задуматься над вопросами жизни и смерти.',2019,2019,'США',54,'18+',7.9,0.00,'ing.jpg','6.jpg','ing.png','ing.mp4','#f4f2f2','Популярное','Джош Шварц','Чарли Пламмер, Кристин Фросет, Дензел Лав, Джей Ли',0,1,9916,'2026-11-19 12:39:05');
/*!40000 ALTER TABLE `titles` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `users` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `last_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Фамилия',
  `first_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Имя',
  `middle_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Отчество',
  `login` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Логин для входа',
  `email` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Электронная почта',
  `password_hash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Хеш пароля (password_hash)',
  `role` enum('user','subscriber','admin') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'user',
  `avatar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Файл аватара в uploads/avatars',
  `status` enum('active','blocked') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_users_login` (`login`),
  UNIQUE KEY `uq_users_email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Зарегистрированные пользователи сервиса';
/*!40101 SET character_set_client = @saved_cs_client */;

